            qsc.Add("page", "2");
            qsc.Add("sort", "name");
            Console.WriteLine("Query string: {0}", qsc); // search=dotnet&page=2&sort=name

            // Create from an existing URI query string.
            var fromUrl = new QueryStringCollection("?category=books&author=tolkien");
