var created = new DateTime(2024, 1, 2, 3, 4, 5, DateTimeKind.Utc);
var modified = created.AddHours(1);
var entity = new EntityInfo(
    created,
    modified,
    Encoding.UTF8.GetBytes("order-42"),
    EntityDataIntegrityValidation.Strong);

