        {
            [XmlAttribute]
            public Guid Id { get; } = Guid.Empty;

            public List<string> Tags { get; } = new() { "xml", "docfx" };
        }

        private sealed class IgnoredDocument
        {
            [XmlIgnore]
            public string Hidden => "internal";

            public string Visible => "public";
        }
